lists = [['r1', 'r2', 'r3'], ['r2', 'r4', 'r1'], ['r5', 'r2', 'r1']]
scores = {}
for lst in lists:
    for rank, rid in enumerate(lst, 1):
        scores[rid] = scores.get(rid, 0) + 1.0 / (60 + rank)
ranked = sorted(scores.items(), key=lambda kv: -kv[1])
print('archives merged:', len(lists))
print('top result:', ranked[0][0], 'score %.4f' % ranked[0][1])
print('results:', len(ranked))

